{
  "packet_id": "H6-T06-1",
  "claims": [
    {
      "claim_id": "C001",
      "fields": ["state"],
      "component": {
        "component_id": "C001",
        "value": "Disagreement among the activity, survey and workload records does not establish that their timing is wrong.",
        "scope": "The records proposed for analysis at the two branches.",
        "provenance": {
          "refs": [
            {"source_id": "P002", "role": "SUPPORT"},
            {"source_id": "P001", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P002 states the inferential restriction; P001 identifies the records."
        }
      }
    },
    {
      "claim_id": "C002",
      "fields": ["state"],
      "component": {
        "component_id": "C002",
        "value": "Before treating disagreement as a timing problem, audit whether the records cover comparable periods, opening hours and populations.",
        "scope": "The preliminary comparability audit of the two branches' records.",
        "provenance": {
          "refs": [
            {"source_id": "P002", "role": "SUPPORT"},
            {"source_id": "P001", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P002 specifies the preliminary audit and its dimensions; P001 identifies its objects."
        }
      }
    },
    {
      "claim_id": "C003",
      "fields": ["state"],
      "component": {
        "component_id": "C003",
        "value": "Uncertain record dates are a possibility to investigate, not an established feature of the available evidence.",
        "scope": "The mapping's starting assumptions about calendar placement.",
        "provenance": {
          "refs": [{"source_id": "P003", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly withholds the assumption that dates are uncertain."
        }
      }
    },
    {
      "claim_id": "C004",
      "fields": ["state"],
      "component": {
        "component_id": "C004",
        "value": "Missing reporting intervals are a possibility to investigate, not an established feature of the available evidence.",
        "scope": "The mapping's starting assumptions about reporting completeness.",
        "provenance": {
          "refs": [{"source_id": "P003", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly treats missing intervals as unverified."
        }
      }
    },
    {
      "claim_id": "C005",
      "fields": ["state"],
      "component": {
        "component_id": "C005",
        "value": "The existence of sufficient historical overlap must be checked rather than assumed.",
        "scope": "The historical records available for alignment.",
        "provenance": {
          "refs": [{"source_id": "P003", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly treats sufficient overlap as a possibility, not a supplied fact."
        }
      }
    },
    {
      "claim_id": "C006",
      "fields": ["state"],
      "component": {
        "component_id": "C006",
        "value": "Recorded zero activity must be distinguished from missing data.",
        "scope": "Interpretation of activity records.",
        "provenance": {
          "refs": [{"source_id": "P004", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly states this distinction."
        }
      }
    },
    {
      "claim_id": "C007",
      "fields": ["operation"],
      "component": {
        "component_id": "C007",
        "value": "Historical sequences assembled before the trial should use the finest time resolution that is both common to the records and reliable.",
        "scope": "Preparation of overlapping historical sequences; availability of sufficient overlap is not asserted.",
        "provenance": {
          "refs": [
            {"source_id": "P005", "role": "SUPPORT"},
            {"source_id": "P003", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P005 supplies the resolution constraint; P003 preserves the uncertainty about overlap."
        }
      }
    },
    {
      "claim_id": "C008",
      "fields": ["operation"],
      "component": {
        "component_id": "C008",
        "value": "Historical sequence preparation should preserve the distinction between weekday and weekend activity.",
        "scope": "The pretrial preparation of comparable sequences.",
        "provenance": {
          "refs": [{"source_id": "P005", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly requires retaining this distinction."
        }
      }
    },
    {
      "claim_id": "C009",
      "fields": ["operation"],
      "component": {
        "component_id": "C009",
        "value": "Activity should be normalized for actual opening hours when preparing historical sequences.",
        "scope": "Pretrial activity comparison; no particular normalization formula is supplied.",
        "provenance": {
          "refs": [{"source_id": "P005", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states the normalization requirement without specifying a formula."
        }
      }
    },
    {
      "claim_id": "C010",
      "fields": ["operation"],
      "component": {
        "component_id": "C010",
        "value": "The timeline should be anchored using verified dates.",
        "scope": "Construction of the timeline used for record comparison.",
        "provenance": {
          "refs": [{"source_id": "P006", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly specifies the required basis for timeline anchors."
        }
      }
    },
    {
      "claim_id": "C011",
      "fields": ["operation"],
      "component": {
        "component_id": "C011",
        "value": "Alignment comparison should examine ordered changes around several distinctive events, with term transitions and transport changes offered as examples.",
        "scope": "The proposed comparison procedure; the examples are not asserted to provide distinctive usable patterns.",
        "provenance": {
          "refs": [{"source_id": "P007", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span specifies multiple distinctive events and identifies the examples as illustrative."
        }
      }
    },
    {
      "claim_id": "C012",
      "fields": ["operation"],
      "component": {
        "component_id": "C012",
        "value": "Only records with genuinely uncertain calendar placement may be shifted; securely dated evidence must not be moved to remove disagreement.",
        "scope": "Eligibility for temporal realignment, without asserting that any eligible records exist.",
        "provenance": {
          "refs": [
            {"source_id": "P007", "role": "SUPPORT"},
            {"source_id": "P010", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "The two spans state complementary formulations of the same restriction."
        }
      }
    },
    {
      "claim_id": "C013",
      "fields": ["operation"],
      "component": {
        "component_id": "C013",
        "value": "Any shift of a genuinely uncertain record must stay within documented plausible bounds.",
        "scope": "Permissible shifts of records eligible for realignment.",
        "provenance": {
          "refs": [{"source_id": "P007", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies both the eligibility condition and the bound on shifting."
        }
      }
    },
    {
      "claim_id": "C014",
      "fields": ["operation", "signal"],
      "component": {
        "component_id": "C014",
        "value": "Accepting an alignment requires repeated correspondence in the timing and order of distinctive changes across independent anchors and overlapping records; one appealing match is insufficient.",
        "scope": "A necessary acceptance condition for a proposed alignment, not a guarantee that it is correct.",
        "provenance": {
          "refs": [
            {"source_id": "P008", "role": "SUPPORT"},
            {"source_id": "P015", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P008 states the acceptance restriction; P015 specifies the temporal correspondence sought."
        }
      }
    },
    {
      "claim_id": "C015",
      "fields": ["signal"],
      "component": {
        "component_id": "C015",
        "value": "The correspondence sought for a candidate alignment should include overlapping records or periods that were not used to choose that alignment.",
        "scope": "Validation of the candidate against independently anchored records.",
        "provenance": {
          "refs": [{"source_id": "P015", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly includes overlaps excluded from alignment selection."
        }
      }
    },
    {
      "claim_id": "C016",
      "fields": ["operation", "signal"],
      "component": {
        "component_id": "C016",
        "value": "Possible missing, duplicated or misassigned intervals should trigger verification against original logs; an unexplained gap or duplication is not grounds for automatic correction.",
        "scope": "Responses to suspected interval anomalies, without assuming that those anomalies have been established.",
        "provenance": {
          "refs": [
            {"source_id": "P009", "role": "SUPPORT"},
            {"source_id": "P017", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P009 specifies verification of suspected anomalies; P017 states the check-versus-correction distinction."
        }
      }
    },
    {
      "claim_id": "C017",
      "fields": ["operation"],
      "component": {
        "component_id": "C017",
        "value": "Periods that remain unresolved after investigation should retain their uncertain status.",
        "scope": "Unresolved periods in the interval-verification procedure.",
        "provenance": {
          "refs": [{"source_id": "P009", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly requires leaving unresolved periods uncertain."
        }
      }
    },
    {
      "claim_id": "C018",
      "fields": ["operation"],
      "component": {
        "component_id": "C018",
        "value": "The proposed reversible three-month transfer of weekday hours to weekends at the two branches is conditional on a roster demonstrating compliance with the existing staffing budget.",
        "scope": "The proposed trial; budget feasibility is a condition, not an established result.",
        "provenance": {
          "refs": [{"source_id": "P011", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the trial bounds and the roster-based budget condition."
        }
      }
    },
    {
      "claim_id": "C019",
      "fields": ["operation"],
      "component": {
        "component_id": "C019",
        "value": "Explicit numerical criteria for meaningful access gains and acceptable weekday losses, workload and service reliability should be set before launch.",
        "scope": "Predeclaration of trial evaluation criteria; no actual numerical thresholds are supplied.",
        "provenance": {
          "refs": [{"source_id": "P012", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span specifies the timing, numerical form and dimensions of the proposed criteria."
        }
      }
    },
    {
      "claim_id": "C020",
      "fields": ["operation"],
      "component": {
        "component_id": "C020",
        "value": "The original schedule should be preserved so that it can be restored.",
        "scope": "The proposed provision for trial reversibility.",
        "provenance": {
          "refs": [{"source_id": "P013", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly links preservation to restoration."
        }
      }
    },
    {
      "claim_id": "C021",
      "fields": ["operation"],
      "component": {
        "component_id": "C021",
        "value": "Where available, unchanged branches and comparable historical periods should be used to check seasonal influences.",
        "scope": "A conditional comparison procedure, without asserting that these comparisons exist or identify causal effects.",
        "provenance": {
          "refs": [{"source_id": "P014", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span supplies the comparison rationale and availability condition."
        }
      }
    },
    {
      "claim_id": "C022",
      "fields": ["signal"],
      "component": {
        "component_id": "C022",
        "value": "Different measures need not exhibit matching magnitudes.",
        "scope": "Cross-measure correspondence in the alignment procedure.",
        "provenance": {
          "refs": [{"source_id": "P016", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly removes matching magnitude as a necessary feature."
        }
      }
    },
    {
      "claim_id": "C023",
      "fields": ["signal"],
      "component": {
        "component_id": "C023",
        "value": "Different measures need not change in matching directions.",
        "scope": "Cross-measure correspondence in the alignment procedure.",
        "provenance": {
          "refs": [{"source_id": "P016", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly removes matching direction as a necessary feature."
        }
      }
    },
    {
      "claim_id": "C024",
      "fields": ["signal"],
      "component": {
        "component_id": "C024",
        "value": "Any expected correspondence between different measures must have a stated reason.",
        "scope": "Expectations used to interpret cross-measure patterns.",
        "provenance": {
          "refs": [{"source_id": "P016", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span directly requires a reason for an expected correspondence."
        }
      }
    },
    {
      "claim_id": "C025",
      "fields": ["signal"],
      "component": {
        "component_id": "C025",
        "value": "Trial observations should be placed on the checked timeline with school-term and transport changes marked.",
        "scope": "The proposed observation protocol for use, access, unmet-need reports, workload, costs and service failures.",
        "provenance": {
          "refs": [{"source_id": "P018", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span specifies the temporal and contextual treatment of the listed observations."
        }
      }
    },
    {
      "claim_id": "C026",
      "fields": ["signal"],
      "component": {
        "component_id": "C026",
        "value": "The listed trial observations are proposed measurements, not established findings.",
        "scope": "At least the immediately preceding trial-observation list; whether the qualifier also refers to earlier alignment signals is not explicit.",
        "provenance": {
          "refs": [
            {"source_id": "P019", "role": "SUPPORT"},
            {"source_id": "P018", "role": "CONTEXT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P019 states the qualifier and P018 supplies its immediate referent; the component does not assert a broader referent."
        }
      }
    },
    {
      "claim_id": "C027",
      "fields": ["inference", "limit"],
      "component": {
        "component_id": "C027",
        "value": "Repeated, independently checked temporal matches would support assigning uncertain records to particular periods, but exact dates should not be assigned while several alignments remain plausible.",
        "scope": "Conditional temporal assignment, not proof of a unique alignment.",
        "provenance": {
          "refs": [
            {"source_id": "P020", "role": "SUPPORT"},
            {"source_id": "P027", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P020 supplies the conditional inference; P027 supplies the restriction on exact assignment."
        }
      }
    },
    {
      "claim_id": "C028",
      "fields": ["inference"],
      "component": {
        "component_id": "C028",
        "value": "Repeated, independently checked temporal matches would support checking the shared timeline through genuine overlaps.",
        "scope": "Conditional checking of chronology where genuine overlap exists.",
        "provenance": {
          "refs": [{"source_id": "P020", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly states this conditional use of matching."
        }
      }
    },
    {
      "claim_id": "C029",
      "fields": ["inference"],
      "component": {
        "component_id": "C029",
        "value": "Repeated, independently checked temporal matches would support extending the shared timeline through genuine overlaps.",
        "scope": "Conditional extension of chronology where genuine overlap exists.",
        "provenance": {
          "refs": [{"source_id": "P020", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly states this conditional extension inference."
        }
      }
    },
    {
      "claim_id": "C030",
      "fields": ["inference"],
      "component": {
        "component_id": "C030",
        "value": "Temporal assignment and timeline checking supported by repeated independent matches would make disagreements among the evidence more interpretable.",
        "scope": "A proposed interpretive benefit of supported alignment, without requiring disagreements to disappear.",
        "provenance": {
          "refs": [
            {"source_id": "P020", "role": "SUPPORT"},
            {"source_id": "P021", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P020 supplies the antecedent and its conditions; P021 states the interpretive consequence."
        }
      }
    },
    {
      "claim_id": "C031",
      "fields": ["inference"],
      "component": {
        "component_id": "C031",
        "value": "Disagreeing evidence may concern different periods.",
        "scope": "One possible interpretation of disagreement, not an established diagnosis.",
        "provenance": {
          "refs": [{"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly presents differing periods as a possibility."
        }
      }
    },
    {
      "claim_id": "C032",
      "fields": ["inference"],
      "component": {
        "component_id": "C032",
        "value": "Evidence may remain substantively different after temporal alignment.",
        "scope": "A possible outcome after alignment; temporal reconciliation need not resolve substantive disagreement.",
        "provenance": {
          "refs": [{"source_id": "P021", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly preserves the possibility of substantive differences after alignment."
        }
      }
    },
    {
      "claim_id": "C033",
      "fields": ["inference"],
      "component": {
        "component_id": "C033",
        "value": "Temporal alignment alone would not demonstrate unmet demand.",
        "scope": "The evidential reach of alignment by itself.",
        "provenance": {
          "refs": [{"source_id": "P022", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly denies this inference from alignment alone."
        }
      }
    },
    {
      "claim_id": "C034",
      "fields": ["inference"],
      "component": {
        "component_id": "C034",
        "value": "Temporal alignment alone would not demonstrate that weekend opening causes a benefit.",
        "scope": "The causal reach of alignment by itself.",
        "provenance": {
          "refs": [{"source_id": "P022", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly denies this causal inference from alignment alone."
        }
      }
    },
    {
      "claim_id": "C035",
      "fields": ["inference"],
      "component": {
        "component_id": "C035",
        "value": "At midpoint and end reviews, aligned evidence and predeclared criteria should support recommending retention of the schedule if access gains meet the threshold and weekday losses, workload and costs remain acceptable.",
        "scope": "A conditional recommendation rule; continuation beyond the trial still requires a separate decision.",
        "provenance": {
          "refs": [
            {"source_id": "P023", "role": "SUPPORT"},
            {"source_id": "P024", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P023 states the review rule and joint conditions; P024 limits what a retention recommendation authorizes."
        }
      }
    },
    {
      "claim_id": "C036",
      "fields": ["inference"],
      "component": {
        "component_id": "C036",
        "value": "At midpoint and end reviews, aligned evidence and predeclared criteria should support recommending a changed allocation if benefits are concentrated in particular hours.",
        "scope": "A conditional recommendation rule; the mapping gives no priority rule for simultaneous recommendation triggers.",
        "provenance": {
          "refs": [{"source_id": "P023", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states concentration in particular hours as a trigger for changing allocation."
        }
      }
    },
    {
      "claim_id": "C037",
      "fields": ["inference"],
      "component": {
        "component_id": "C037",
        "value": "At midpoint and end reviews, aligned evidence and predeclared criteria should support recommending a changed allocation if benefits are concentrated in particular branches.",
        "scope": "A conditional recommendation rule; the mapping gives no priority rule for simultaneous recommendation triggers.",
        "provenance": {
          "refs": [{"source_id": "P023", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span states concentration in particular branches as a trigger for changing allocation."
        }
      }
    },
    {
      "claim_id": "C038",
      "fields": ["inference"],
      "component": {
        "component_id": "C038",
        "value": "At midpoint and end reviews, aligned evidence and predeclared criteria should support recommending restoration of the original schedule if benefits fall short.",
        "scope": "A conditional recommendation rule using the predeclared criteria, without supplied threshold values.",
        "provenance": {
          "refs": [{"source_id": "P023", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span identifies insufficient benefits as a restoration trigger."
        }
      }
    },
    {
      "claim_id": "C039",
      "fields": ["inference"],
      "component": {
        "component_id": "C039",
        "value": "At midpoint and end reviews, aligned evidence and predeclared criteria should support recommending restoration of the original schedule if harms exceed limits.",
        "scope": "A conditional recommendation rule using the predeclared criteria, without supplied limit values.",
        "provenance": {
          "refs": [{"source_id": "P023", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span identifies excessive harms as a restoration trigger."
        }
      }
    },
    {
      "claim_id": "C040",
      "fields": ["inference", "limit"],
      "component": {
        "component_id": "C040",
        "value": "Continuation beyond the three-month trial requires a separate decision, including separate authorization for an extension when evidence remains inadequate at expiry.",
        "scope": "Authorization beyond the bounded trial; a trial recommendation does not itself supply that authorization.",
        "provenance": {
          "refs": [
            {"source_id": "P024", "role": "SUPPORT"},
            {"source_id": "P030", "role": "SUPPORT"}
          ],
          "support_status": "SUFFICIENT",
          "rationale": "P024 states the general continuation requirement; P030 restates it for an extension under inadequate evidence."
        }
      }
    },
    {
      "claim_id": "C041",
      "fields": ["limit"],
      "component": {
        "component_id": "C041",
        "value": "Branch-specific events can produce false or ambiguous temporal alignments.",
        "scope": "A possible alignment failure source, not a finding that such events have distorted these records.",
        "provenance": {
          "refs": [{"source_id": "P025", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span lists branch-specific events among possible causes of false or ambiguous alignment."
        }
      }
    },
    {
      "claim_id": "C042",
      "fields": ["limit"],
      "component": {
        "component_id": "C042",
        "value": "Weak shared seasonal effects can produce false or ambiguous temporal alignments.",
        "scope": "A possible limitation of the common temporal signal, not an established condition of these records.",
        "provenance": {
          "refs": [{"source_id": "P025", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly lists weak shared seasonal effects as an alignment risk."
        }
      }
    },
    {
      "claim_id": "C043",
      "fields": ["limit"],
      "component": {
        "component_id": "C043",
        "value": "Repetitive weekly patterns can produce false or ambiguous temporal alignments.",
        "scope": "A possible pattern-related alignment failure.",
        "provenance": {
          "refs": [{"source_id": "P025", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly lists repetitive weekly patterns as an alignment risk."
        }
      }
    },
    {
      "claim_id": "C044",
      "fields": ["limit"],
      "component": {
        "component_id": "C044",
        "value": "Reporting errors can produce false or ambiguous temporal alignments.",
        "scope": "A possible data-quality failure, without asserting that reporting errors occurred.",
        "provenance": {
          "refs": [{"source_id": "P025", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly lists reporting errors as an alignment risk."
        }
      }
    },
    {
      "claim_id": "C045",
      "fields": ["limit"],
      "component": {
        "component_id": "C045",
        "value": "Faulty date anchors can produce false or ambiguous temporal alignments.",
        "scope": "A possible reference-date failure, without asserting that any anchor is faulty.",
        "provenance": {
          "refs": [{"source_id": "P025", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly lists faulty date anchors as an alignment risk."
        }
      }
    },
    {
      "claim_id": "C046",
      "fields": ["limit"],
      "component": {
        "component_id": "C046",
        "value": "Insufficient overlap can produce false or ambiguous temporal alignments.",
        "scope": "A possible overlap limitation, without asserting that available overlap is insufficient.",
        "provenance": {
          "refs": [{"source_id": "P025", "role": "SUPPORT"}],
          "support_status": "SUFFICIENT",
          "rationale": "The span explicitly lists insufficient overlap as an alignment risk."
        }
      }
    },
    {
      "claim_id": "C047",
      "fields": ["limit"],
      "component": {
        "component_id": "C047",
        "value": "Survey responses, attendance, door counts and workload measure different things.",
        "scope": "The distinction among the evidential measures used by the mapping.",
        "provenance": {
